/*
 Problem: 3336. Find the Number of Subsequences With Equal GCD
 Language: cpp
 Runtime: 379 ms (92.67%)
 Memory: 290.1 MB (55.11%)
 Tags: Array, Math, Dynamic Programming, Number Theory, Euclidean Algorithm, Greatest Common Divisor
*/
class Solution {
public:
    int subsequencePairCount(vector<int>& nums) {
        int mx = *max_element(nums.begin(), nums.end());
        int MOD = 1e9 + 7;
        vector<vector<int>> dp(mx + 1, vector<int>(mx + 1));
        dp[0][0] = 1;

        for (const auto& x : nums) {
            auto ndp = dp;

            for (int g1 = 0; g1 <= mx; ++g1) {
                for (int g2 = 0; g2 <= mx; ++g2) {
                    if (!dp[g1][g2]) continue;

                    int ng1 = g1 == 0 ? x : std::gcd(g1, x);
                    int ng2 = g2 == 0 ? x : std::gcd(g2, x);

                    ndp[ng1][g2] += dp[g1][g2];
                    if (ndp[ng1][g2] >= MOD) ndp[ng1][g2] -= MOD;

                    ndp[g1][ng2] += dp[g1][g2];
                    if (ndp[g1][ng2] >= MOD) ndp[g1][ng2] -= MOD;
                }
            }

            dp.swap(ndp);
        }

        long long ans = 0;

        for (int g = 1; g <= mx; ++g) {
            ans += dp[g][g];
            ans %= MOD;
        }

        return (int)ans;
    }
};
